import pytest

from tallyho import prorate_cents


def test_full_period():
    assert prorate_cents(3000, 30, 30) == 3000


def test_zero_days():
    assert prorate_cents(3000, 0, 30) == 0


def test_half_period():
    assert prorate_cents(3000, 15, 30) == 1500


def test_rounds_half_up():
    assert prorate_cents(1001, 15, 30) == 501


def test_rounds_down_below_half():
    assert prorate_cents(1000, 1, 3) == 333


def test_rounds_up_above_half():
    assert prorate_cents(1000, 2, 3) == 667


def test_leap_february():
    assert prorate_cents(2900, 14, 29) == 1401


def test_days_used_out_of_range():
    with pytest.raises(ValueError):
        prorate_cents(3000, 31, 30)


def test_negative_days_used():
    with pytest.raises(ValueError):
        prorate_cents(3000, -1, 30)

